exec(open(__file__.replace("c2.py","lib.py")).read())
glic = C.glic
OK=(True,None); NA=(False,"licensure_delegator_not_authority"); CT=(False,"licence_class_not_trusted"); LP=(False,"lapsed")
AF = dict(C.AFD1, official="O")
CS = lambda i, of, k="O", names=None: ST.R(i,"countersign",k,tuple(names or (of,)),of=of)
off = lambda S: sorted(ST.Seats(S).holders(ST.OFFICER,"af"))
LSO = ST.offer("lso","A",("X",),"license","af","group",("af",),head=("af",),counted=ST.OFFICER); LSA = ST.accept("lsa","X","lso")
run("C2a lone officer A confers license on X, no countersign", [AF,LSO,LSA,A("e","RD","af"),glic("l","af","X")|{"names":("lsa",)}], "RD","l", want=NA)
run("C2b + O's countersign (licence names it)", [AF,LSO,LSA,CS("cs","lso"),A("e","RD","af"),glic("l","af","X")|{"names":("lsa","cs")}], "RD","l", want=OK)
run("C2b' O's countersign held, the licence does not name it", [AF,LSO,LSA,CS("cs","lso"),A("e","RD","af"),glic("l","af","X")|{"names":("lsa",)}], "RD","l")
run("C2c A's own licence for af (the one officer's quorum), no countersign", [AF,A("e","RD","af"),glic("l","af","A")], "RD","l")
run("C2c' a countersign by A itself on its licence", [AF,A("e","RD","af"),glic("l","af","A"),CS("cs","l","A")], "RD","l")
DEN = "dental"
RCH = ST.offer("rch","A",(),"record","af","group",("af",),head=("af",),counted=ST.OFFICER,declared_cohort="affiliations",licence_classes=((M,True),(L,False),(DEN,False)),official="O")
run("C2d A's record change adding dental, no countersign; A's dental licence", [AF,RCH,A("e","RD","af"),glic("l","af","A",cls=DEN)|{"names":("rch",)}], "RD","l", want=CT)
run("C2d' + O's countersign", [AF,RCH,CS("cs","rch"),A("e","RD","af"),glic("l","af","A",cls=DEN)|{"names":("rch","cs")}], "RD","l", want=OK)
RCO = dict(RCH, id="rco", official="Z")
run("C2e A's record change naming a new official Z, countersigned by Z", [AF,RCO,CS("cs","rco","Z"),A("e","RD","af"),glic("l","af","A",cls=DEN)|{"names":("rco","cs")}], "RD","l", want=CT)
DIS = ST.offer("dis","A",(),"record","af","group",("af",),head=("af",),counted=ST.OFFICER,dissolved_at=100)
run("C2f A dissolves alone, no countersign; A's licence after", [AF,DIS,A("e","RD","af"),glic("l","af","A")|{"names":("dis",)}], "RD","l", want=OK, extra=lambda S: ST.Seats(S).dissolved("af"))
run("C2f' + O's countersign; A's licence after", [AF,DIS,CS("cs","dis"),A("e","RD","af"),glic("l","af","A")|{"names":("dis","cs")}], "RD","l", want=NA, extra=lambda S: ST.Seats(S).dissolved("af"))
run("C2f'' countersigned dissolution; A's licence from before (stood)", [AF,A("e","RD","af"),glic("l","af","A"),dict(DIS,names=("af","l")),CS("cs","dis")], "RD","l", want=LP)
WD = ST.withdraw("wd","A","lso",("lso",))
run("C2g A withdraws lso; O's countersign concurrent with the withdrawal", [AF,LSO,LSA,WD,CS("cs","lso"),A("e","RD","af"),glic("l","af","X")|{"names":("lsa","cs")}], "RD","l", want=NA)
